'use strict';
(async()=>{
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);let tab=params.get('tab')||'assets',page=0,filtered=[],assets=[],maps=[],records=[];const size=36;
const image=a=>a.image?`<img loading="lazy" src="data/visual/${esc(a.image)}" alt="${esc(a.displayName||a.name)}">`:'<div class="placeholder">Preview unavailable</div>';
const recordURL=r=>`index.html?record=${encodeURIComponent(r.id)}&table=${encodeURIComponent(r.table)}#${encodeURIComponent(r.table)}`;
function apply(){page=0;const q=$('#query').value.toLowerCase().trim(),cat=$('#category').value,status=$('#status').value;let source=tab==='maps'?maps:tab==='assets'?assets:records.filter(r=>r.table===({heroes:'heroes',monsters:'monsters',items:'static-items'}[tab]));filtered=source.filter(r=>(!q||[r.name,r.displayName,r.bundle,...r.aliases||[],...(r.tilesets||[])].join(' ').toLowerCase().includes(q))&&(!cat||tab!=='assets'||r.category===cat)&&(!status||(r.status||(r.image?'ready':'unavailable'))===status));$('#summary').textContent=`${filtered.length.toLocaleString()} matching ${tab==='maps'?'maps':tab==='assets'?'graphics':'records'}`;render()}
function render(){const slice=filtered.slice(page*size,(page+1)*size);$('#grid').innerHTML=slice.map(r=>tab==='maps'?`<a class="card" href="${r.status==='ready'?'map-preview.html?map='+encodeURIComponent(r.name):'#'}" ${r.status==='ready'?'':`data-unavailable="${esc(r.name)}"`}>${r.image?image(r):'<div class="placeholder">Unsupported / unavailable</div>'}<div class="info"><strong>${esc(r.name)}</strong><small>${r.status==='ready'?`${r.tiles.toLocaleString()} tiles · ${r.layers} layers · ${Math.round(100*r.artworkTiles/Math.max(1,r.tiles))}% static artwork`:esc(r.error)}</small></div></a>`:tab==='assets'?`<button class="card" data-asset="${r.id}">${image(r)}<span class="info"><strong>${esc(r.name||r.type)}</strong><small class="alias">${esc((r.aliases||[]).join(' · '))}</small><small>${esc(r.presentation||r.type)} · ${r.width||'?'} × ${r.height||'?'}</small><small>${esc(r.bundle.split('/Android/').pop())}</small></span></button>`:`<a class="card" href="${recordURL(r)}">${image(r)}<div class="info"><strong>${esc(r.displayName||r.name)}</strong>${r.displayName?`<small class="alias">${esc(r.name)}</small>`:''}<small>#${r.id} · ${esc(r.presentation)}</small></div></a>`).join('')||'<p>No matches. Try another name or clear the filters.</p>';$('#prev').disabled=page===0;$('#next').disabled=(page+1)*size>=filtered.length;$('#page').textContent=`${filtered.length?page+1:0} / ${Math.ceil(filtered.length/size)}`}
function switchTab(t){tab=['assets','heroes','monsters','items','maps'].includes(t)?t:'assets';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#category').hidden=tab!=='assets';const p=new URLSearchParams({tab,q:$('#query').value});history.replaceState(null,'','?'+p);apply()}
try{const load=async name=>{const r=await fetch('data/visual/'+name+'.json');if(!r.ok)throw Error(name+' catalog unavailable');return r.json()};[assets,maps,records]=await Promise.all([load('assets'),load('maps'),load('records')]);$('#query').value=params.get('q')||'';switchTab(tab);let timer;$('#query').oninput=()=>{clearTimeout(timer);timer=setTimeout(apply,160)};$('#category').onchange=$('#status').onchange=apply;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('#prev').onclick=()=>{page--;render()};$('#next').onclick=()=>{page++;render()};$('#grid').onclick=e=>{if(e.target.closest('[data-unavailable]')){e.preventDefault();return}const b=e.target.closest('[data-asset]');if(!b)return;const a=assets.find(a=>a.id===b.dataset.asset);$('#detail-body').innerHTML=`<h2>${esc(a.name||a.type)}</h2>${image(a)}<p>${esc(a.presentation||a.type)} · original ${a.width||'?'} × ${a.height||'?'} px · ${esc(a.status)}</p><p>${esc(a.bundle)}</p>${a.error?`<p>Unresolved: ${esc(a.error)}</p>`:''}${a.image?`<a href="data/visual/${esc(a.image)}" target="_blank" rel="noopener">Open image preview ↗</a>`:''}<h3>Associated entries</h3><div class="record-links">${(a.records||[]).map(r=>`<a href="${recordURL(r)}">${esc(r.displayName||r.name)} · ${esc(r.table)} #${r.id}</a>`).join('')||'<p>No verified record association.</p>'}</div>`;$('#detail').showModal()};$('#close').onclick=()=>$('#detail').close()}catch(e){$('#summary').textContent='Unable to load the visual library: '+e.message}
})();
